                            modifier = Modifier.size(24.dp)
                        )
                    },
                    title = "Terms of Service",
                    description = "Read our terms and conditions"
                )
            }
        }
        Spacer(modifier = Modifier.padding(8.dp))

        // LOGOUT BUTTON
        ProfileSettingCard("Logout") {
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .clickable {
                        AuthHelper.logout()
