// Setting Card Component
@Composable
fun ProfileSettingCard(
    category: String = "Settings",
    cardContent: @Composable () -> Unit
) {
    Text(
        text = category,
        fontSize = 18.sp,
        fontWeight = FontWeight.Bold,
        color = Color(0xFF2D2D2D),
        modifier = Modifier.padding(start = 16.dp, bottom = 8.dp)
    )
    Card(
        modifier = Modifier
            .fillMaxWidth()
            .padding(horizontal = 16.dp),
        colors = CardDefaults.cardColors(containerColor = Color.White),
        elevation = CardDefaults.cardElevation(defaultElevation = 2.dp)
    ) {
        // Card Content
        Column(
            modifier = Modifier
                .fillMaxWidth()
                .padding(20.dp)
        ) {
            cardContent()
        }
    }
}

// Card Content Component
@Composable
fun SettingCardContent(
    onClickAction: () -> Unit,
    iconContent: @Composable () -> Unit,
    title: String,
    description: String
) {
    Row(
        modifier = Modifier
            .fillMaxWidth()
            .clickable { onClickAction() },
        verticalAlignment = Alignment.CenterVertically
    ) {
        Box(
            modifier = Modifier
                .size(40.dp),
            contentAlignment = Alignment.Center
        ) {
            // Render the provided icon composable (could be an Icon with painterResource)
            iconContent()
        }

        Spacer(modifier = Modifier.width(12.dp))

        Column(modifier = Modifier.weight(1f)) {
            Text(
                text = title,
                fontSize = 14.sp,
                color = Color(0xFF2D2D2D),
                fontWeight = FontWeight.Medium
            )
            Text(
                text = description,
                fontSize = 12.sp,
                color = Color.Gray,
                modifier = Modifier.padding(top = 2.dp)
            )
        }
    }
}

//@Preview(showBackground = true)
@Composable
fun UserStatus(categoryStatus: String, statusValue: String? = "No Information") {
    Card(
        modifier = Modifier.size(180.dp),
        colors = CardDefaults.cardColors(containerColor = Color.Red)
    ) {
        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(16.dp),
            horizontalAlignment = Alignment.CenterHorizontally,
            verticalArrangement = Arrangement.Center
        ) {
            Text(
                text = categoryStatus,
                color = Color.White,
                fontSize = 14.sp,
                fontWeight = FontWeight.Bold,
                textAlign = TextAlign.Center
            )

            Icon(
                imageVector = if (categoryStatus == "Smoking") Icons.Default.Clear else Icons.Default.Check, // CHANGE THIS TO A RELEVANT ICON
                contentDescription = "statusIcon",
                tint = Color.White,
                modifier = Modifier
                    .size(32.dp)
                    .padding(vertical = 8.dp)
            )

            Text(
                text = statusValue ?: "No Information",
                color = Color.White,
                fontSize = 16.sp,
                fontWeight = FontWeight.Bold,
                textAlign = TextAlign.Center
            )
        }
    }
}

