            }
        }
        Spacer(modifier = Modifier.padding(8.dp))

        ProfileSettingCard("App Preferences") {
            Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                SettingCardContent(
                    onClickAction = {},
