                        )
                    },
                    title = "Notifications",
                    description = "Turn on/off notifications"
                )
            }
        }
        Spacer(modifier = Modifier.padding(8.dp))

        ProfileSettingCard("Health Information") {
            Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                SettingCardContent(
                    onClickAction = {},
                    iconContent = {
                        Image(
