                            contentDescription = "connectedDevice",
                            modifier = Modifier.size(24.dp)
                        )
                    },
                    title = "Connected Device",
                    description = "View and manage connected health devices"
                )
                SettingCardContent(
                    onClickAction = {},
                    iconContent = {
                        Image(
